"""
sandbox.py — Strategy sandbox: A/B test strategies on same topic via replay.

Orchestrates replay across all candidate strategies after each verdict,
stores results for fitness evaluation.
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

from .schema import Strategy
from .replay_engine import ReplayEngine, CounterfactualVerdict

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_DEFAULT_RESULTS_PATH = _REPO_ROOT / "data" / "evolution" / "sandbox-results.jsonl"


@dataclass
class SandboxResult:
    case_id: str
    timestamp: str
    active_strategy_id: str
    active_verdict: str
    counterfactuals: dict[str, dict] = field(default_factory=dict)
    actual_outcome: Optional[str] = None

    def to_dict(self) -> dict:
        return {
            "case_id": self.case_id,
            "timestamp": self.timestamp,
            "active_strategy_id": self.active_strategy_id,
            "active_verdict": self.active_verdict,
            "counterfactuals": self.counterfactuals,
            "actual_outcome": self.actual_outcome,
        }


class StrategySandbox:
    def __init__(
        self,
        replay_engine: Optional[ReplayEngine] = None,
        results_path: Optional[Path] = None,
    ):
        self.engine = replay_engine or ReplayEngine()
        self.results_path = Path(results_path or _DEFAULT_RESULTS_PATH)
        self.results_path.parent.mkdir(parents=True, exist_ok=True)

    def run_replay(
        self,
        case_id: str,
        active_strategy: Strategy,
        candidates: list[Strategy],
        active_verdict: str = "",
    ) -> SandboxResult:
        """
        Replay a case through all candidate strategies.
        Called automatically after each /stage0 verdict.
        """
        all_strategies = [s for s in candidates if s.id != active_strategy.id]
        all_strategies.append(active_strategy)

        counterfactual_map = self.engine.replay_case(case_id, all_strategies)

        counterfactuals = {}
        for sid, cv in counterfactual_map.items():
            counterfactuals[sid] = {
                "strategy_name": cv.strategy_name,
                "score": cv.score,
                "verdict": cv.verdict,
                "confidence": cv.confidence,
                "dimension_scores": cv.dimension_scores,
            }

        result = SandboxResult(
            case_id=case_id,
            timestamp=datetime.now(timezone.utc).isoformat(),
            active_strategy_id=active_strategy.id,
            active_verdict=active_verdict,
            counterfactuals=counterfactuals,
        )

        self._persist(result)
        logger.info(
            "Sandbox replay: case=%s, %d strategies evaluated",
            case_id, len(counterfactuals),
        )
        return result

    def record_outcome(self, case_id: str, actual_outcome: str) -> None:
        """Update sandbox result with actual outcome once known."""
        results = self._load_results()
        updated = False
        for r in results:
            if r.get("case_id") == case_id:
                r["actual_outcome"] = actual_outcome
                updated = True

        if updated:
            self._save_all(results)
            logger.info("Recorded outcome for case %s: %s", case_id, actual_outcome)

    def get_results_for_strategy(
        self, strategy_id: str, with_outcome_only: bool = True
    ) -> list[dict]:
        """Get all sandbox results where this strategy was evaluated."""
        results = self._load_results()
        matching = []
        for r in results:
            if strategy_id in r.get("counterfactuals", {}):
                if with_outcome_only and not r.get("actual_outcome"):
                    continue
                matching.append(r)
        return matching

    def get_strategy_accuracy(self, strategy_id: str) -> Optional[float]:
        """Fraction of cases where strategy's verdict matched actual outcome."""
        results = self.get_results_for_strategy(strategy_id, with_outcome_only=True)
        if not results:
            return None

        correct = 0
        for r in results:
            cf = r["counterfactuals"].get(strategy_id, {})
            cf_verdict = cf.get("verdict", "")
            actual = r.get("actual_outcome", "")
            if self._verdict_matches_outcome(cf_verdict, actual):
                correct += 1

        return correct / len(results)

    def _verdict_matches_outcome(self, verdict: str, outcome: str) -> bool:
        """Check if strategy verdict aligns with actual outcome."""
        outcome_lower = outcome.lower()
        if verdict == "GO":
            return outcome_lower in ("success", "profitable", "go", "positive")
        elif verdict == "NO-GO":
            return outcome_lower in ("failure", "loss", "no-go", "negative", "killed")
        return False

    def _persist(self, result: SandboxResult):
        with open(self.results_path, "a", encoding="utf-8") as f:
            f.write(json.dumps(result.to_dict(), ensure_ascii=False) + "\n")

    def _load_results(self) -> list[dict]:
        if not self.results_path.exists():
            return []
        results = []
        for line in self.results_path.read_text(encoding="utf-8").strip().split("\n"):
            if line.strip():
                try:
                    results.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
        return results

    def _save_all(self, results: list[dict]):
        with open(self.results_path, "w", encoding="utf-8") as f:
            for r in results:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")

