"""
safety.py — Strategy-level safety harness.

Enforces:
- Mandatory gates in all strategies
- Min agent counts
- Max divergence from seed
- Auto-rollback on 3 consecutive regressions
- Kill switch via flag file
- Feature flag via environment variable
"""

from __future__ import annotations

import json
import logging
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .schema import Strategy, MANDATORY_GATES, MIN_WAVE1_COUNT, MIN_WAVE2_COUNT

logger = logging.getLogger(__name__)

_REPO_ROOT = Path(__file__).resolve().parents[5]
_KILL_SWITCH_PATH = _REPO_ROOT / "data" / "config" / "strategy-evolution-kill.flag"
_BRIER_PATH = _REPO_ROOT / "data" / "calibration" / "brier-scores.jsonl"

MAX_DIVERGENCE_FROM_SEED = 0.7
CONSECUTIVE_REGRESSION_LIMIT = 3
BRIER_REGRESSION_THRESHOLD = 0.1


@dataclass
class StrategySafetyViolation:
    rule: str
    message: str

    def to_dict(self) -> dict:
        return {"rule": self.rule, "message": self.message}


@dataclass
class StrategySafetyResult:
    allowed: bool
    violations: list[StrategySafetyViolation] = field(default_factory=list)

    def to_dict(self) -> dict:
        return {
            "allowed": self.allowed,
            "violations": [v.to_dict() for v in self.violations],
        }


class StrategySafetyHarness:
    def __init__(self, seed_strategy: Optional[Strategy] = None):
        self._seed = seed_strategy

    def is_system_enabled(self) -> bool:
        """Check feature flag + kill switch."""
        if _KILL_SWITCH_PATH.exists():
            return False
        env_flag = os.environ.get("STRATEGY_EVOLUTION_ENABLED", "true")
        return env_flag.lower() in ("true", "1", "yes")

    def validate_strategy(self, strategy: Strategy) -> StrategySafetyResult:
        """Validate strategy against all safety rules."""
        violations = []

        for gate in MANDATORY_GATES:
            if gate not in strategy.gate_sequence:
                violations.append(StrategySafetyViolation(
                    rule="mandatory_gate",
                    message=f"Missing mandatory gate: {gate}",
                ))

        if strategy.wave1_count < MIN_WAVE1_COUNT:
            violations.append(StrategySafetyViolation(
                rule="min_wave1_count",
                message=f"wave1_count={strategy.wave1_count} < {MIN_WAVE1_COUNT}",
            ))

        if strategy.wave2_count < MIN_WAVE2_COUNT:
            violations.append(StrategySafetyViolation(
                rule="min_wave2_count",
                message=f"wave2_count={strategy.wave2_count} < {MIN_WAVE2_COUNT}",
            ))

        if self._seed:
            distance = strategy.jaccard_distance(self._seed)
            if distance > MAX_DIVERGENCE_FROM_SEED:
                violations.append(StrategySafetyViolation(
                    rule="max_divergence",
                    message=f"Jaccard distance {distance:.2f} > max {MAX_DIVERGENCE_FROM_SEED}",
                ))

        if strategy.mountain_rubric:
            total = sum(strategy.mountain_rubric.values())
            if abs(total - 1.0) > 0.02:
                violations.append(StrategySafetyViolation(
                    rule="rubric_sum",
                    message=f"Rubric weights sum to {total:.3f}, expected ~1.0",
                ))

        return StrategySafetyResult(
            allowed=len(violations) == 0,
            violations=violations,
        )

    def check_rollback_needed(
        self,
        strategy_id: str,
        baseline_brier: float,
    ) -> bool:
        """Check if strategy needs auto-rollback (3 consecutive worse Brier)."""
        recent_briers = self._get_recent_briers(strategy_id, n=CONSECUTIVE_REGRESSION_LIMIT)
        if len(recent_briers) < CONSECUTIVE_REGRESSION_LIMIT:
            return False

