                record = json.loads(line)
                if record.get("_strategy_id") == strategy_id:
                    brier = record.get("brier_score", record.get("score"))
                    if brier is not None:
                        scores.append(brier)
        except (json.JSONDecodeError, OSError):
            pass

        return scores[-n:]


